def merge(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    return out + a[i:] + b[j:]

def msort(xs):
    if len(xs) < 2:
        return xs
    m = len(xs) // 2
    return merge(msort(xs[:m]), msort(xs[m:]))

import time

def timed(fn):
    def w(*a, **k):
        t = time.perf_counter()
        try:
            return fn(*a, **k)
        finally:
            print(fn.__name__, round(time.perf_counter() - t, 4))
    return w

@timed
def slow(n):
    return sum(i * i for i in range(n))

