class LRU:
    def __init__(self, cap):
        self.cap, self.d = cap, {}

    def get(self, k):
        if k not in self.d:
            return None
        v = self.d.pop(k)
        self.d[k] = v      # dicts keep insertion order, so re-insert = most recent
        return v

    def put(self, k, v):
        self.d.pop(k, None)
        self.d[k] = v
        if len(self.d) > self.cap:
            del self.d[next(iter(self.d))]

import random

def shuffle_deal(n_players, hand=5):
    deck = [r + s for r in "23456789TJQKA" for s in "shdc"]
    random.shuffle(deck)
    return [deck[i * hand:(i + 1) * hand] for i in range(n_players)]

